_SD_BUS_SLOT = const(3)
_SD_BUS_FREQ = const(32_000_000)
_SD_BUS_SCK = const(14)
_SD_BUS_MISO = const(12)
_SD_BUS_MOSI = const(13)
_SD_BUS_CS = const(15)

_RTC_FAST_CLK_HZ = const(8_000_000)
_RTCCNTL_REG_BASE = const(0x3ff48000)
_RTC_RTCIO_GPIO_BASE = const(0x3ff48400)
