@micropython.viper
def jit_sample_buf(dest: ptr32, src: ptr8, len: int, delta_cycles: int):
    #global max_amp, min_amp

    rtc_word_len = (len - 1) * 2

    for rtc_addr in range(0, rtc_word_len, 2):
        sample_addr: int = rtc_addr >> 1

        #print(f"src offset {src_offset} idx {src_offset + (rtc_addr >> 3)}")
        sample = src[sample_addr]
        #print(f"got sample {sample} at idx {sample_addr}")
        dest[rtc_addr] = (_ULP_INSTR_REG_WR_TEMPLATE | (sample << _ULP_INSTR_REG_WR_DATA_OFFSET))
        dest[rtc_addr + 1] = uint(_ULP_INSTR_WAIT_TEMPLATE) | delta_cycles

        # # FOR TESTING REASONS
        # if sample > int(max_amp):
        #     max_amp = sample
        # elif sample < int(min_amp):
        #     min_amp = sample

    # NOTE: Last sample in the array has extra wait cycles (due to branching logic)
    # Account for this in the wait logic.
    dest[rtc_word_len] = (_ULP_INSTR_REG_WR_TEMPLATE | (sample << _ULP_INSTR_REG_WR_DATA_OFFSET))
    dest[rtc_word_len + 1] = uint(_ULP_INSTR_WAIT_TEMPLATE) | (delta_cycles - 25)

@micropython.viper
def memset_zeros_buf(dest: ptr32, len: int, delta_cycles: int):
    d_wr = (127 << _ULP_INSTR_REG_WR_DATA_OFFSET)

    for rtc_addr in range(0, len * 2, 2):
        dest[rtc_addr] = _ULP_INSTR_REG_WR_TEMPLATE | d_wr
        dest[rtc_addr + 1] = int(_ULP_INSTR_WAIT_TEMPLATE) | delta_cycles

def memdmp_sample_buf(src: ptr32, len: int):
    for rtc_addr in range(0, len, 8):
        instr_dac = mem32[src + rtc_addr]
        instr_wait = mem32[src + rtc_addr + 4] 

        print(f"addr {hex(src + rtc_addr)}: dac instr {hex(instr_dac)} dac val {hex(instr_dac >> _ULP_INSTR_REG_WR_DATA_OFFSET & 0xFF)} wait instr {hex(instr_wait)} cycles {instr_wait & 0xFFFF}")

def gen_memdmp_binary(src: ptr32, len: int):
    out = [b"ulp\x00", b"\x00\x00", int.to_bytes(0x5888, 2), b"\x00\x00\x00\x00"]

    for rtc_addr in range(0, len, 8):
        out.append(int.to_bytes(mem32[src + rtc_addr], 4, 'little'))
        out.append(int.to_bytes(mem32[src + rtc_addr + 4], 4, 'little'))

    return b"".join(out)

def firm_entry(_, _2):
    try:
        firm_payload()
    except Exception as ie:
        sys.print_exception(ie)
        from bootrom import reboot_to_uart
        reboot_to_uart()

